    # Calculates hash code according to all attributes.
    # @return [Integer] Hash code
    def hash
      [id, public_token, barcode, merchant_receipt_id, merchant_name, merchant_logo, store_id, organisation_id, transaction_date, order_number, cashier, items, subtotal, tax_amount, discount_amount, tip_amount, total_amount, currency, payment_info, qr_code_url, qr_token, qr_expires_at, receipt_url, pdf_url, notes, return_policy, offers, offer_policies, feedback_url, loyalty_info, merchant_details, adjustments, transaction_references, warranties, insights, return_insights, access_count, last_accessed, status, expires_at, created_at, updated_at].hash
